// Some portions generated by Codex
package org.eclipse.rdf4j.queryrender;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.queryrender.sparql.SPARQLQueryRenderer;
import org.eclipse.rdf4j.queryrender.sparql.experimental.SparqlQueryRenderer;
import org.junit.jupiter.api.Test;

class ExplicitEmptyReadDatasetRenderingTest {

	@Test
	void legacyRendererRejectsEmptyReadSelectionForEveryQueryForm() {
		rejectsEmptyReadSelectionForEveryQueryForm(false);
	}

	@Test
	void experimentalRendererRejectsEmptyReadSelectionForEveryQueryForm() {
		rejectsEmptyReadSelectionForEveryQueryForm(true);
	}

	private static void rejectsEmptyReadSelectionForEveryQueryForm(boolean experimental) {
		QueryRenderer renderer = renderer(experimental);
		for (String query : List.of("SELECT * WHERE { ?s ?p ?o }", "ASK { ?s ?p ?o }",
				"CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o }", "DESCRIBE ?s WHERE { ?s ?p ?o }")) {
			var parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
			parsed.setDataset(emptyDataset());
			assertThatThrownBy(() -> renderer.render(parsed)).isInstanceOf(IllegalArgumentException.class)
					.hasMessageContaining("empty read dataset");
		}
	}

	@Test
	void legacyRendererPreservesUnconfiguredAndNonemptySelections() throws Exception {
		preservesUnconfiguredAndNonemptySelections(false);
	}

	@Test
	void experimentalRendererPreservesUnconfiguredAndNonemptySelections() throws Exception {
		preservesUnconfiguredAndNonemptySelections(true);
	}

	private static void preservesUnconfiguredAndNonemptySelections(boolean experimental) throws Exception {
		QueryRenderer renderer = renderer(experimental);
		var parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, "SELECT * WHERE { ?s ?p ?o }", null);
		String absent = renderer.render(parsed);
		parsed.setDataset(new SimpleDataset());
		assertThat(renderer.render(parsed)).isEqualTo(absent);
		SimpleDataset selected = new SimpleDataset();
		selected.addDefaultGraph(SimpleValueFactory.getInstance().createIRI("urn:default"));
		selected.addNamedGraph(SimpleValueFactory.getInstance().createIRI("urn:named"));
		parsed.setDataset(selected);
		String expected = renderer.render(parsed);
		selected.setExplicitReadDataset(true);
		assertThat(renderer.render(parsed)).isEqualTo(expected);
		var roundTrip = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, expected, null);
		assertThat(roundTrip.getDataset().getDefaultGraphs()).isEqualTo(selected.getDefaultGraphs());
		assertThat(roundTrip.getDataset().getNamedGraphs()).isEqualTo(selected.getNamedGraphs());
	}

	@Test
	void rejectsEmptyUpdateReadSelectionIncludingWriteTargets() {
		var update = QueryParserUtil.parseUpdate(QueryLanguage.SPARQL,
				"DELETE { ?s ?p ?o } WHERE { ?s ?p ?o }", null);
		SimpleDataset dataset = emptyDataset();
		dataset.addDefaultRemoveGraph(SimpleValueFactory.getInstance().createIRI("urn:remove"));
		update.map(update.getUpdateExprs().get(0), dataset);
		assertThatThrownBy(() -> new SparqlQueryRenderer().render(update))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("empty read dataset");
	}

	private static QueryRenderer renderer(boolean experimental) {
		return experimental ? new SparqlQueryRenderer() : new SPARQLQueryRenderer();
	}

	private static SimpleDataset emptyDataset() {
		SimpleDataset dataset = new SimpleDataset();
		dataset.setExplicitReadDataset(true);
		return dataset;
	}
}
